import { WorkOrder } from "@ontology/sdk";
import { Client } from "@osdk/client";
import { createEditBatch, Edits } from "@osdk/functions";
type E = Edits.Object<WorkOrder>;
export default function defer(client: Client, wo: WorkOrder, days: number): E[] {
  const batch = createEditBatch<E>(client);
  batch.update(wo, { status: "DEFERRED", deferDays: days });
  return batch.getEdits(); }
